function showDelayedOneReply(question,response,status='正在查询…'){
 cancelPendingQuery();const loading=add('ERP ONE助理',status);loading.classList.add('one-query-loading');loading.setAttribute('aria-busy','true');input.disabled=true;send.disabled=true;
 const generation=queryGeneration;queryTimer=setTimeout(()=>{if(generation!==queryGeneration)return;loading.classList.remove('one-query-loading');loading.removeAttribute('aria-busy');renderOneMessage(loading.querySelector('p'),response);saveConversation(question,response);input.disabled=false;send.disabled=!input.value.trim();log.scrollTop=log.scrollHeight;input.focus()},1500);
}
